/** Snap a coordinate to 1mm precision. */
function snap(v: number): number {
  return Math.round(v);
}

function snapPoint(p: Point3D): Point3D {
  return [snap(p[0]), snap(p[1]), snap(p[2])];
}

/** Euclidean distance in mm. */
function distance(a: Point3D, b: Point3D): number {
  return Math.sqrt(
    (b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2 + (b[2] - a[2]) ** 2,
  );
}

function midpoint(a: Point3D, b: Point3D): Point3D {
  return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2, (a[2] + b[2]) / 2];

export function MeasurementTool({ active }: MeasurementToolProps): ReactNode {
  const [points, setPoints] = useState<Point3D[]>([]);

  const handleClick = useCallback(
    (e: ThreeEvent<PointerEvent>) => {
      if (!active) return;
      e.stopPropagation();
      const hit = snapPoint([
        e.point.x,
        e.point.y,
        e.point.z,
      ]);
      setPoints((prev) => {
        // After 2 points, start a new measurement
        if (prev.length >= 2) return [hit];
        return [...prev, hit];
      });
    },
    [active],
  );

  const dist = useMemo(() => {
    const a = points[0];
    const b = points[1];
    if (!a || !b) return null;
    return distance(a, b);
  }, [points]);

  const mid = useMemo(() => {
    const a = points[0];
    const b = points[1];
    if (!a || !b) return null;
    return midpoint(a, b);
  }, [points]);

  if (!active) return null;

return (
